def test_prunetraceback_path1(monkeypatch):
    # create FunctionMixin subclass with config returning options.
    class DummyConfig:
        def getoption(self, name, default=None):
            if name == 'fulltrace':
                return False
            if name == 'tbstyle':
                return 'auto'
            return default
    class DummyFunctionMixin(FunctionMixin):
        def __init__(self):
            self.config = DummyConfig()
            self._obj = lambda: None  # dummy function
    # create dummy excinfo with traceback
    class DummyEntry:
        def __init__(self):
            self.style = None
        def set_repr_style(self, style):
            self.style = style
    class DummyTraceback:
        def __init__(self, frames, cut_equal=True, filter_empty=False):
            self.frames = frames
            self.cut_equal = cut_equal
            self.filter_empty = filter_empty
        def cut(self, path=None, firstlineno=None):
            # if firstlineno is None: second cut
            if firstlineno is None:
                return self if self.cut_equal else DummyTraceback(self.frames, cut_equal=self.cut_equal, filter_empty=self.filter_empty)
            # first cut
            return self if self.cut_equal else DummyTraceback(self.frames, cut_equal=self.cut_equal, filter_empty=self.filter_empty)
        def filter(self, filter_func=None):
