            return self._python_files
        raise KeyError(name)


class DummyHook:
    """Hook proxy stub that returns a sentinel module object."""

    def __init__(self, sentinel):
        self._sentinel = sentinel

    def pytest_pycollect_makemodule(self, fspath, parent):
        # In real pytest this returns a ``Module`` collector.
        # For the purpose of the test we just return the sentinel.
        return self._sentinel


class DummySession:
    """Session stub exposing ``isinitpath`` and ``gethookproxy``."""

    def __init__(self, is_init_path: bool, sentinel):
        self._is_init_path = is_init_path
        self._sentinel = sentinel

    def isinitpath(self, fspath):
        return self._is_init_path

    def gethookproxy(self, fspath):
        return DummyHook(self._sentinel)


class DummyParent:
    """Collector stub with ``session`` and ``config`` attributes."""

    def __init__(self, session: DummySession, config: DummyConfig):
        self.session = session
        self.config = config


@pytest.fixture
def sentinel():
    """A unique object used to recognise a successful collection."""
    return object()


def test_collect_non_py_file_returns_none(sentinel):
    """Path 4 – file suffix is not ``.py``."""
    parent = DummyParent(
        session=DummySession(is_init_path=False, sentinel=sentinel),
        config=DummyConfig(python_files=[]),
