def test_collect_py_not_init_but_matching_init_pattern_returns_module(sentinel):
    """Path 2 – ``.py`` file, not an init path but matches ``__init__.py`` pattern."""
    parent = DummyParent(
        session=DummySession(is_init_path=False, sentinel=sentinel),
        config=DummyConfig(python_files=[]),  # pattern list empty → only '__init__.py' matters
