# collection and fixture machinery.
from _pytest.python import _call_with_optional_argument


def test_call_with_optional_argument_bound_method_with_extra_arg():
    """Path 1: bound method (inspect.ismethod == True) with an extra argument."""
    class C:
        def __init__(self):
            self.called_with = None

        def method(self, value):
            # The method should receive the argument passed by _call_with_optional_argument.
            self.called_with = value

    obj = C()
    # Pass a value; the method expects one argument besides `self`.
    _call_with_optional_argument(obj.method, "expected")
    assert obj.called_with == "expected"


def test_call_with_optional_argument_bound_method_without_extra_arg():
    """Path 2: bound method (inspect.ismethod == True) that takes only `self`."""
    class D:
        def __init__(self):
            self.called = False

        def method(self):
            # No arguments expected; just set a flag.
            self.called = True

    obj = D()
    # The extra argument should be ignored because the method takes no parameters.
    _call_with_optional_argument(obj.method, "ignored")
    assert obj.called is True


def test_call_with_optional_argument_function_with_one_arg():
    """Path 3: plain function (inspect.ismethod == False) that expects one argument."""
    called = {}

    def func(arg):
        called["value"] = arg

    _call_with_optional_argument(func, 123)
    assert called["value"] == 123


def test_call_with_optional_argument_function_without_args():
    """Path 4: plain function (inspect.ismethod == False) that takes no arguments."""
    called = {"flag": False}

    def func():
        called["flag"] = True

    # The extra argument should be ignored because the function takes no parameters.
    _call_with_optional_argument(func, "ignored")
    assert called["flag"] is True
