    """Object without a __new__ attribute should return False."""
    class NoNew:
        pass

    assert hasnew(NoNew) is False
    # Also test an instance of such a class (should also be False)
    assert hasnew(NoNew()) is False


def test_hasnew_with_custom_new():
    """Object with a custom __new__ different from object.__new__ should return True."""
    class CustomNew:
        def __new__(cls, *args, **kwargs):
            # custom implementation, not the same as object.__new__
            return super().__new__(cls)

    assert hasnew(CustomNew) is True


def test_hasnew_with_object_new():
    """Object whose __new__ is exactly object.__new__ should return False."""
    class SameAsObjectNew:
        __new__ = object.__new__

    assert hasnew(SameAsObjectNew) is False
