        """
        Although a normal proxy model always has at least the auto‑created pk,
        we manually clear the field lists to exercise the branch where
        `cls._meta.local_fields or cls._meta.local_many_to_many` is falsy.
        """
        class Dummy(models.Model):
            pass

        # Turn the model into a proxy and wipe its field collections.
        Dummy._meta.proxy = True
        Dummy._meta.local_fields = []
        Dummy._meta.local_many_to_many = []

        # With no fields reported, the check should return an empty list.
