from django.db import models, connections, router
from django.test import SimpleTestCase, isolate_apps, override_settings


# Helper objects to simulate database connections
class DummyFeatures:
    def __init__(self, truncates_names=False):
        self.truncates_names = truncates_names
        self.supports_partial_indexes = True
        self.supports_covering_indexes = True
        self.supports_expression_indexes = True
        self.supports_table_check_constraints = True


class DummyOps:
    def __init__(self, max_name_length):
        self._max_name_length = max_name_length

    def max_name_length(self):
        return self._max_name_length


class DummyConnection:
    def __init__(self, max_name_length, truncates_names=False):
        self.ops = DummyOps(max_name_length)
        self.features = DummyFeatures(truncates_names)
        self.display_name = 'dummy-db'


def set_dummy_connections(db_map):
    """Replace django.db.connections with a dict containing dummy connections."""
    connections._connections = {}
    for alias, conn in db_map.items():
        connections[alias] = conn


def allow_all_migrate(db, model):
    """Router that always allows migration."""
    return True


def disallow_all_migrate(db, model):
    """Router that never allows migration."""
    return False


@isolate_apps('check_framework')
class ModelLongColumnNamesTests(SimpleTestCase):
    """Tests for Model._check_long_column_names."""

    def test_no_databases(self):
        """Path 1 – empty databases list returns no errors."""
        errors = models.Model._check_long_column_names([])
        self.assertEqual(errors, [])

    @mock.patch.object(router, 'allow_migrate_model', side_effect=allow_all_migrate)
    def test_two_databases_allowed_len_set_and_updated(self, _):
        """
        Paths 2–4:
        Two databases, both allow migration.
        First DB sets allowed_len, second DB may update it.
        """
        # First DB: max length 10, second DB: max length 8 (<10) -> allowed_len should be updated to 8.
        set_dummy_connections({
            'db1': DummyConnection(max_name_length=10),
            'db2': DummyConnection(max_name_length=8),
        })
        # Model with a field whose autogenerated column name length is 9 (>8) triggers error.
        long_name = 'x' * 9

