import pytest

from _pytest.junitxml import merge_family


def test_merge_family_simple():
    left = {"a": [1]}
    right = {"b": [2]}
    # Expected: left is updated with concatenated list [1, 2]
    merge_family(left, right)
    assert left == {"a": [1, 2]}


def test_merge_family_multiple_right_keys():
    left = {"a": [1]}
    # Order matters: dict preserves insertion order (b then c)
    right = {"b": [2], "c": [3]}
    merge_family(left, right)
    # The last iteration (c) overwrites the result for key "a"
    assert left == {"a": [1, 3]}


def test_merge_family_multiple_left_keys():
    left = {"a": [1], "x": [10]}
    right = {"b": [2]}
    merge_family(left, right)
    # Both left keys should be updated with the right list
    assert left == {"a": [1, 2], "x": [10, 2]}


def test_merge_family_type_error_on_left_not_list():
    left = {"a": "notalist"}
    right = {"b": [2]}
    with pytest.raises(TypeError) as excinfo:
        merge_family(left, right)
    # The exception should carry the type of the offending value
    assert excinfo.value.args[0] is str


def test_merge_family_type_error_second_key():
    left = {"a": [1], "x": "badvalue"}
    right = {"b": [2]}
    with pytest.raises(TypeError) as excinfo:
        merge_family(left, right)
    # The exception should be raised for the second key
    assert excinfo.value.args[0] is str
