import builtins

import pytest

from matplotlib.style import core as style_core


# Helper to capture calls to the internal warning function.
@pytest.fixture
def warn_recorder(monkeypatch):
    calls = []

    def fake_warn(msg):
        calls.append(msg)

    monkeypatch.setattr(style_core._api, "warn_external", fake_warn)
    return calls


# Choose a known blacklisted key and a safe non‑blacklisted key.
BLACK = next(iter(style_core.STYLE_BLACKLIST))  # e.g. 'backend'
SAFE = "lines.linewidth"


def test_all_blacklisted_warn_true(warn_recorder):
    """Path 1: two blacklisted keys, warn=True → two warnings, empty result."""
    d = {BLACK: "agg", f"{BLACK}_fallback": "module"}
    result = style_core._remove_blacklisted_style_params(d, warn=True)
    assert result == {}
    # Two warnings, one per key, containing the key representation.
    assert len(warn_recorder) == 2
    assert all(str(k) in msg for k, msg in zip(d.keys(), warn_recorder))


def test_black_then_safe_warn_true(warn_recorder):
    """Path 3: first key blacklisted (warn), second safe → warning + kept safe."""
    d = {BLACK: "agg", SAFE: 2.0}
    result = style_core._remove_blacklisted_style_params(d, warn=True)
    assert result == {SAFE: 2.0}
    assert len(warn_recorder) == 1
    assert BLACK in warn_recorder[0]


def test_single_blacklisted_warn_true(warn_recorder):
    """Path 4: single blacklisted key, warn=True → warning, empty result."""
    d = {BLACK: "agg"}
    result = style_core._remove_blacklisted_style_params(d, warn=True)
    assert result == {}
    assert len(warn_recorder) == 1
    assert BLACK in warn_recorder[0]


def test_all_safe_warn_false(warn_recorder):
    """Path 6: two safe keys, warn=False → both kept, no warnings."""
    d = {SAFE: 1.0, "lines.marker": "o"}
    result = style_core._remove_blacklisted_style_params(d, warn=False)
    assert result == d
    assert warn_recorder == []


def test_single_safe_warn_false(warn_recorder):
    """Path 8: single safe key, warn=False → kept, no warnings."""
    d = {SAFE: 1.0}
    result = style_core._remove_blacklisted_style_params(d, warn=False)
    assert result == d
    assert warn_recorder == []


def test_safe_then_black_warn_true(warn_recorder):
    """Path 9: first safe, second blacklisted, warn=True → safe kept, warning emitted."""
    d = {SAFE: 1.0, BLACK: "agg"}
    result = style_core._remove_blacklisted_style_params(d, warn=True)
    assert result == {SAFE: 1.0}
    assert len(warn_recorder) == 1
    assert BLACK in warn_recorder[0]


def result = style_core._remove_blacklisted_style_params(d, warn=False)
    assert result == {SAFE: 1.0}
    assert warn_recorder == []


def test_safe_then_black_warn_false(warn_recorder):
    """Path 10: first safe, second blacklisted, warn=False → safe kept, no warning."""
    d = {SAFE: 1.0, BLACK: "agg"}
    result = style_core._remove_blacklisted_style_params(d, warn=False)
    assert result == {SAFE: 1.0}
    assert warn_recorder == []
