    def __init__(self, ignore_paths=None, ignore_globs=None, options=None):
        # Lists of py.path.local objects (or strings for globs)
        self._ignore_paths = ignore_paths or []
        self._ignore_globs = ignore_globs or []
        self._options = options or {}

