        value = ["not", "a", "string"]
        cls.non_string_error.msg = cls.non_string_error.msg.format(
            value, type(value).__name__
        )

    @override_settings(
        TEMPLATES=[
            {
                "BACKEND": "django.template.backends.django.DjangoTemplates",
                "OPTIONS": {"string_if_invalid": ["not", "a", "string"]},
            },
            {
                "BACKEND": "django.template.backends.django.DjangoTemplates",
                "OPTIONS": {"string_if_invalid": "valid"},
            },
        ]
    )
