from django.core.checks import Error
from django.core.checks.templates import E003, check_for_template_tags_with_the_same_name
from django.test import SimpleTestCase
from django.test.utils import override_settings


class CheckTemplateTagLibrariesAdditionalTests(SimpleTestCase):
    """Additional tests to cover more execution paths of
    ``check_for_template_tags_with_the_same_name``."""

    @override_settings(INSTALLED_APPS=[])
    def test_duplicate_library_name_across_two_template_configs(self):
        """
        The same library name appears in two different TEMPLATES configurations
        with different module paths – this should produce a single error.
        """
        TEMPLATES = [
            {
                "BACKEND": "django.template.backends.django.DjangoTemplates",
                "OPTIONS": {
                    "libraries": {
                        "dup_lib": "app_one.templatetags.lib",
                    },
                },
            },
            {
                "BACKEND": "django.template.backends.django.DjangoTemplates",
                "OPTIONS": {
                    "libraries": {
                        "dup_lib": "app_two.templatetags.lib",
                    },
                },
            },
        ]
        with self.settings(TEMPLATES=TEMPLATES):
            expected_error = Error(
                E003.msg.format(
                    repr("dup_lib"),
                    ", ".join(
                        repr(p)
                        for p in sorted(
                            [
                                "app_one.templatetags.lib",
                                "app_two.templatetags.lib",
                            ]
                        )
                    ),
                ),
                id=E003.id,
            )
            self.assertEqual(
                check_for_template_tags_with_the_same_name(None), [expected_error]
            )

    @override_settings(INSTALLED_APPS=[])
    def test_one_duplicate_and_one_unique_library(self):
        """
        Two libraries are defined: one appears twice (different paths) and the
        other appears only once. Only the duplicate should trigger an error.
        """
        TEMPLATES = [
            {
                "BACKEND": "django.template.backends.django.DjangoTemplates",
                "OPTIONS": {
                    "libraries": {
                        "dup_lib": "app_one.templatetags.lib",
                        "unique_lib": "app_one.templatetags.unique",
                    },
                },
            },
            {
                "BACKEND": "django.template.backends.django.DjangoTemplates",
                "OPTIONS": {
                    "libraries": {
                        "dup_lib": "app_two.templatetags.lib",
                    },
                },
            },
        ]
        with self.settings(TEMPLATES=TEMPLATES):
            expected_error = Error(
                E003.msg.format(
